<?php
require __DIR__.'/app/bootstrap.php';maintenance_gate();require_writable_forum();$topic=(int)($_GET['topic']??$_POST['topic']??0);$post=(int)($_GET['post']??$_POST['post']??0);
$s=db()->prepare('SELECT t.id FROM topics t JOIN categories c ON c.id=t.category_id WHERE t.id=? AND t.is_hidden=0 AND c.is_visible=1');$s->execute([$topic]);if(!$s->fetchColumn()){http_response_code(404);exit('Тему не знайдено');}
if($post){$s=db()->prepare('SELECT id FROM posts WHERE id=? AND topic_id=? AND is_hidden=0');$s->execute([$post,$topic]);if(!$s->fetchColumn()){http_response_code(404);exit('Пост не знайдено');}}
$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$reason=trim((string)($_POST['reason']??''));if($reason!==''&&mb_strlen($reason)<=2000){db()->prepare('INSERT INTO reports(user_id,topic_id,post_id,reason) VALUES(?,?,?,?)')->execute([current_user_id(),$topic,$post?:null,$reason]);$done=true;}}
forum_header('Скарга');?><section class="page-title"><h1>Повідомити про порушення</h1></section><?php if($done):?><p class="notice success">Скаргу передано адміністратору.</p><?php else:?><form method="post" class="panel stack settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="topic" value="<?=$topic?>"><input type="hidden" name="post" value="<?=$post?>"><label>Причина<textarea name="reason" maxlength="2000" required></textarea></label><button class="btn primary">Надіслати скаргу</button></form><?php endif;forum_footer();
